        ones = torch.ones(x.shape, dtype=x.dtype, device=x.device)
        bias = torch.full(x.shape, -0.125, dtype=x.dtype, device=x.device)
        entry = (ones, bias)
        _CONST_CACHE[key] = entry
    return entry


